%% Benchmark1.m
% ==========================================================================
% BENCHMARK I: Communication Design Only (CD) — Fixed Circular Trajectory
%
% This benchmark scheme fixes the UIRS and UCJ trajectories to the initial
% circular paths (generated by Feasible_Init.m) and only optimises the
% communication design variables:
%   - User scheduling (alpha)
%   - AP transmit power (p_a)
%   - UCJ peak AN power (p_j)
%   - IRS beamforming (Phi)
%
% Reference: Section IV-B, Benchmark I in the paper.
%
% Usage: Run SystemParams.m in the workspace before calling this script.
% ==========================================================================

ite_index = 1;

% Feasible initialisation (circular trajectory — kept fixed throughout)
Feasible_Init
print_results(ATR, APC, AEE);
Visulization

Out_itr = 1;
uavTrj(qr, qj, fig1_ax, lgd, Out_itr);
Itr(Out_itr).alpha    = alpha;
Itr(Out_itr).pa       = pa;
Itr(Out_itr).pj       = pj;
Itr(Out_itr).Qr       = {qr, vr};
Itr(Out_itr).Qj       = {qj, vj};
Itr(Out_itr).mAEE     = AEE(end);
Itr(Out_itr).APC      = APC(end);
Itr(Out_itr).mACT     = ATR(end);
Itr(Out_itr).AEE_Outer = AEE(end);
AEE_Outer(Out_itr)    = AEE(end);

while (~strcmp(flag, 'converged'))

    fprintf('\n Iteration #%d starts now ...\n', Out_itr);
    Out_itr = Out_itr + 1;

    % Sub-problem 1: User Scheduling
    fprintf('\n User scheduling is being optimized...\n')
    subProb1_Alt
    print_results(ATR, APC, AEE);

    % Sub-problem 2: IRS Beamforming
    ite_index = ite_index + 1;
    subProb2_NEW
    print_results(ATR, APC, AEE);

    % Sub-problem 3: Joint Power Allocation
    ite_index = ite_index + 1;
    fprintf('\n Joint network power allocation is being optimized... \n')
    subProb3_Alt
    print_results(ATR, APC, AEE);

    % NOTE: Trajectory is NOT updated (Benchmark I — CD only)

    % Record iteration state
    Itr(Out_itr).alpha     = alpha;
    Itr(Out_itr).pa        = pa;
    Itr(Out_itr).pj        = pj;
    Itr(Out_itr).Qr        = {qr, vr};
    Itr(Out_itr).Qj        = {qj, vj};
    Itr(Out_itr).mAEE      = AEE(end);
    Itr(Out_itr).APC       = APC(end);
    Itr(Out_itr).mACT      = ATR(end);
    AEE_Outer(Out_itr)     = AEE(end);
    Itr(Out_itr).AEE_Outer = AEE(end);
    uavTrj(qr, qj, fig1_ax, lgd, Out_itr);

    if ((AEE_Outer(Out_itr) - AEE_Outer(Out_itr-1)) / AEE_Outer(Out_itr-1) <= eps_algo)
        fprintf('\nBenchmark I (CD) converged in %d outer iterations.\n', Out_itr);
        flag = 'converged';
    end

end

figure;
plot(1:ite_index, AEE, '-sb', 'LineWidth', 1.5, 'MarkerSize', 4);
xlabel('Inner Iteration Index'); ylabel('mAEE');
title('Convergence — Benchmark I (CD, Fixed Trajectory)'); grid on;
